def iscube(a):
    if a == 0:
        return True

    abs_a = abs(a)
    # Estimate the cube root
    n = round(abs_a ** (1/3))

    # Check nearby values due to floating point imprecision
    for candidate in [n - 1, n, n + 1]:
        if candidate >= 0 and candidate ** 3 == abs_a:
            return True

    return False

def add(lst):
    """Given a non-empty list of integers lst. add the even elements that are at odd indices.


    Examples:
        add([4, 2, 6, 7]) ==> 2 
    """
    total = 0
