def sort_array(arr):
    """
    In this Kata, you have to sort an array of non-negative integers according to
    number of ones in their binary representation in ascending order.
    For similar number of ones, sort based on decimal value.

    It must be implemented like this:
    >>> sort_array([1, 5, 2, 3, 4]) == [1, 2, 3, 4, 5]
    >>> sort_array([-2, -3, -4, -5, -6]) == [-6, -5, -4, -3, -2]
    >>> sort_array([1, 0, 2, 3, 4]) == [0, 1, 2, 3, 4]
    """
    def count_ones(n):
        return bin(n).count('1') if n >= 0 else bin(n & 0xFFFFFFFF).count('1')

    return sorted(arr, key=lambda x: (count_ones(x), x))

def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the
    alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    Examples
    split_words("Hello world!") ➞ ["Hello", "world!"]
    split_words("Hello,world!") ➞ ["Hello", "world!"]
    split_words("abcdef") == 3 
    '''
    # Check for whitespace
    if any(c.isspace() for c in txt):
        return txt.split()

    # Check for commas
    if ',' in txt:
        return txt.split(',')

    # Count lowercase letters with odd order in alphabet
    count = 0
    for c in txt:
        if c.islower():
            order = ord(c) - ord('a')
            if order % 2 == 0:
                count += 1

    return count

def tri(n):
    if n == 0:
        return [1]

    result = [0] * (n + 1)
    result[0] = 1  # tri(0) = 1 + 0/2 = 1

    if n >= 1:
        result[1] = 3  # tri(1) = 3

    for i in range(2, n + 1):
        if i % 2 == 0:
            # even: tri(i) = 1 + i / 2
            result[i] = 1 + i // 2
        else:
            # odd: tri(i) = tri(i-1) + tri(i-2) + tri(i+1)
            # but tri(i+1) for odd i means i+1 is even, so tri(i+1) = 1 + (i+1)/2
            result[i] = result[i - 1] + result[i - 2] + (1 + (i + 1) // 2)

    return result

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,
    """
    def to_float(val):
        if isinstance(val, str):
            return float(val.replace(',', '.'))
        else:
            return float(val)

    a_float = to_float(a)
    b_float = to_float(b)

    if a_float > b_float:
        return a
    elif b_float > a_float:
        return b
    else:
        return None

def sum_squares(lst):
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0:
            total += val ** 3
        else:
            total += val
    return total

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) returns (1, 1)
        even_odd_count(123) returns (1, 2)
    """
    even_count = 0
    odd_count = 0

    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    return (even_count, odd_count)

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if text == "":
        return None
    return hashlib.md5(text.encode('utf-8')).hexdigest()
